import {icon,logo} from './icons.js';
import {btn,publicNav,publicFooter} from './marketing-ui.js';
import {loopSculpture,connectedSequence} from './graphics.js';
export function landingPage(home,modules){return `<div class="landing">${publicNav()}<main><section class="landing-hero"><div class="hero-stage"><div class="hero-copy"><div class="hero-eyebrow"><span></span> A LITTLE LESS FRICTION. A LOT MORE FLOW.</div><h1>Everything your team needs.<br><em>Finally working together.</em></h1><p>Conversations, plans, knowledge, and meetings.<br>One thoughtful workspace that connects it all.</p><div class="hero-actions">${btn('Explore the demo','explore','primary','arrow')}${btn('Join the waitlist','waitlist','glass')}</div><div class="hero-caption">Independent by design. Connected by default.</div></div>${loopSculpture()}</div><div class="app-preview reveal" aria-label="Preview of the implemented Loop workspace"><div class="preview-rail">${logo}${['home','chat','calendar','docs','projects','ai'].map(x=>icon(x,19)).join('')}</div><div class="preview-inner"><div class="preview-top"><span>✦ &nbsp; Loop <span class="muted">/ Home</span></span><span class="demo-label"><i></i>Interactive demo</span></div><div class="preview-content" inert>${home()}</div></div><button class="preview-open btn primary" data-action="explore">Step inside the workspace ${icon('arrow',17)}</button></div></section><section id="connected" class="connected-section reveal"><span class="eyebrow">THE SPACE BETWEEN TOOLS, FINALLY CONNECTED</span><div class="section-intro"><h2>Work doesn’t happen<br>in separate tabs.</h2><p>A conversation sparks a decision. A meeting moves it forward. A plan gives it a home. Loop keeps the context with the work, from the first thought to the next step.</p></div>${connectedSequence()}</section><section id="workspace" class="module-section reveal"><div class="section-intro"><h2>One workspace.<br>A more coherent day.</h2><p>Start with what matters. Move naturally between the conversation, the plan, and the knowledge behind it.</p></div><div class="module-showcase"><div class="module-description"><span class="eyebrow">YOUR WORK, IN HARMONY</span><h3>Everything has a place.<br>Nothing loses its context.</h3><p>Built for the way teams actually work: a little planning, a little conversation, a lot of shared understanding.</p>${btn('Find your flow','explore','quiet','arrow')}</div><div class="module-list">${modules.filter(([id])=>id!=='activity'&&id!=='ai').map(([id,label])=>`<button data-action="landing-module" data-id="${id}">${icon(id,22)}<span>${label}<small>${{home:'The important things, brought into focus.',chat:'Conversations that move work forward.',calendar:'Shared time, thoughtfully arranged.',docs:'A home for everything your team knows.',meetings:'From preparation to follow-through.',projects:'Clear owners. Visible momentum.'}[id]}</small></span>${icon('arrow',18)}</button>`).join('')}</div></div></section><section id="intelligence" class="intelligence-section reveal"><div><span class="eyebrow">CONTEXTUAL AI. HUMAN JUDGMENT.</span><h2>A step ahead.<br>Always on your terms.</h2><p>Loop AI can connect the dots, prepare the next step, and bring the right context into focus. You review the details. You decide what happens next.</p><span class="small-text muted">Explore prepared AI scenarios in the interactive demo.</span></div><div class="landing-ai-card"><div class="eyebrow">${icon('ai',20)} LOOP AI</div><p>The onboarding copy will be ready tomorrow. There’s room for a launch review at 3 PM.</p><div class="landing-proposal">${icon('calendar',23)}<span><b>Launch copy review</b><small>Tomorrow · 3:00–3:30 PM</small></span><span class="badge">For your review</span></div>${btn('Explore AI approvals','landing-module','primary','arrow','data-id="ai"')}<small>Suggested → Reviewed → Applied</small></div></section><section class="waitlist-section reveal" id="waitlist"><div class="waitlist-orb">${logo}</div><span class="eyebrow">A MORE THOUGHTFUL WAY TO WORK</span><h2>Let’s bring it together.</h2><p>Be part of what comes next for Loop.</p>${btn('Join the waitlist','waitlist','primary','arrow')}<small>Prototype preview. Form collection is local until configured.</small></section></main>${publicFooter()}</div>`}
